import React, { useEffect, useMemo, useState } from 'react';
import './dashboard.css';
import { getNotifications, getProjects, getTasks } from './api';

const navItems = [
  { label: 'Dashboard', icon: '⌂', active: true },
  { label: 'Tasks', icon: '✓' },
  { label: 'Calendar', icon: '▣' },
  { label: 'Projects', icon: '▦' },
  { label: 'Team', icon: '♙' },
];

const toolItems = [
  { label: 'Notifications', icon: '◉' },
  { label: 'Analytics', icon: '◔' },
  { label: 'Settings', icon: '⚙' },
];

function Dashboard({ user, userName = 'there', userRole = 'User', onLogout }) {
  const [tasks, setTasks] = useState([]);
  const [projects, setProjects] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    let mounted = true;
    async function loadDashboard() {
      setLoading(true);
      setError('');
      try {
        const [taskResponse, projectResponse, notificationResponse] = await Promise.all([
          getTasks(),
          getProjects(),
          getNotifications(),
        ]);
        if (!mounted) return;
        setTasks(Array.isArray(taskResponse?.data) ? taskResponse.data : []);
        setProjects(Array.isArray(projectResponse?.data) ? projectResponse.data : []);
        setNotifications(Array.isArray(notificationResponse?.data) ? notificationResponse.data : []);
      } catch (err) {
        if (mounted) setError(err.message || 'Unable to load dashboard data.');
      } finally {
        if (mounted) setLoading(false);
      }
    }
    loadDashboard();
    return () => { mounted = false; };
  }, []);

  const stats = useMemo(() => {
    const completed = tasks.filter((task) => task.completed || task.status === 'completed').length;
    const progress = tasks.filter((task) => task.status === 'in-progress').length;
    const today = new Date();
    today.setHours(23, 59, 59, 999);
    const overdue = tasks.filter((task) => {
      if (!task.dueDate || task.completed || task.status === 'completed') return false;
      return new Date(task.dueDate) < today;
    }).length;
    return { total: tasks.length, completed, progress, overdue };
  }, [tasks]);

  const taskBreakdown = useMemo(() => {
    const total = tasks.length || 1;
    const completed = tasks.filter((t) => t.completed || t.status === 'completed').length;
    const progress = tasks.filter((t) => t.status === 'in-progress').length;
    const pending = Math.max(tasks.length - completed - progress, 0);
    return [
      { label: 'Completed', value: completed, percent: Math.round((completed / total) * 100), className: 'completed' },
      { label: 'In progress', value: progress, percent: Math.round((progress / total) * 100), className: 'progress' },
      { label: 'Pending', value: pending, percent: Math.round((pending / total) * 100), className: 'pending' },
    ];
  }, [tasks]);

  const recentTasks = tasks.slice(0, 6);
  const recentProjects = projects.slice(0, 3);
  const unreadNotifications = notifications.filter((item) => !item.read).length;

  return (
    <div className="dashboard-page">
      <div className="dashboard-shell">
        <aside className="sidebar">
          <div>
            <div className="brand">
              <div className="brand-mark">N</div>
              <div>
                <strong>Nexdo</strong>
                <span>Workspace</span>
              </div>
            </div>

            <div className="workspace-pill">
              <div className="workspace-icon">N</div>
              <div>
                <strong>My Workspace</strong>
                <span>{userRole}</span>
              </div>
              <span className="chevron">⌄</span>
            </div>

            <SidebarSection title="Overview" items={navItems} />
            <SidebarSection title="Manage" items={toolItems} notificationCount={unreadNotifications} />
          </div>

          <div className="sidebar-bottom">
            <div className="upgrade-card">
              <span className="sparkle">✦</span>
              <strong>Stay on top of your work</strong>
              <p>Plan tasks, track progress and keep your team aligned.</p>
            </div>

            <button className="sidebar-link" type="button">
              <span>?</span> Help & Support
            </button>

            <div className="profile-mini">
              <div className="avatar">{getInitials(userName)}</div>
              <div className="profile-copy">
                <strong>{userName}</strong>
                <span>{user?.email || 'Workspace member'}</span>
              </div>
              <button type="button" className="logout-btn" onClick={onLogout} title="Log out">↪</button>
            </div>
          </div>
        </aside>

        <main className="dashboard-main">
          <header className="topbar">
            <div className="mobile-brand">
              <div className="brand-mark">N</div>
              <strong>Nexdo</strong>
            </div>
            <div className="breadcrumb">Workspace <span>/</span> Overview</div>
            <div className="topbar-actions">
              <button className="icon-btn" type="button" title="Search">⌕</button>
              <button className="icon-btn notification-btn" type="button" title="Notifications">♢{unreadNotifications > 0 && <b>{unreadNotifications}</b>}</button>
              <div className="top-avatar">{getInitials(userName)}</div>
            </div>
          </header>

          <div className="content">
            <section className="hero">
              <div>
                <span className="eyebrow">GOOD TO SEE YOU</span>
                <h1>Good morning, {userName.split(' ')[0]} <span>✦</span></h1>
                <p>Here’s a quick look at what’s happening across your workspace.</p>
              </div>
              <button className="primary-btn" type="button">
                <span>+</span> Create new task
              </button>
            </section>

            {error && <div className="dashboard-alert">{error}</div>}

            <section className="stats-grid">
              <StatCard title="Total tasks" value={stats.total} helper="All assigned tasks" icon="✓" tone="orange" loading={loading} />
              <StatCard title="In progress" value={stats.progress} helper="Currently being worked on" icon="◷" tone="pink" loading={loading} />
              <StatCard title="Completed" value={stats.completed} helper="Finished successfully" icon="✓" tone="green" loading={loading} />
              <StatCard title="Overdue" value={stats.overdue} helper="Need your attention" icon="!" tone="red" loading={loading} />
            </section>

            <section className="section-heading">
              <div>
                <span className="section-kicker">WORKSPACE</span>
                <h2>Project overview</h2>
              </div>
              <button type="button" className="text-btn">View all projects →</button>
            </section>

            <section className="project-grid">
              {loading ? <LoadingCards /> : recentProjects.length ? recentProjects.map((project, index) => (
                <ProjectCard key={project._id || project.id || project.name} project={project} index={index} taskCount={tasks.filter((t) => String(t.project?._id || t.project) === String(project._id || project.id)).length} />
              )) : <EmptyCard text="No projects yet. Create your first project to get started." />}
            </section>

            <div className="dashboard-grid">
              <section className="panel tasks-panel">
                <div className="panel-header">
                  <div>
                    <span className="section-kicker">YOUR WORK</span>
                    <h2>Recent tasks</h2>
                  </div>
                  <button type="button" className="small-btn">View all</button>
                </div>
                <div className="task-list">
                  {loading ? <TaskLoadingRows /> : recentTasks.length ? recentTasks.map((task) => <TaskRow key={task._id || task.id} task={task} />) : <EmptyCard text="No tasks found for this workspace." />}
                </div>
              </section>

              <aside className="side-panels">
                <section className="panel progress-panel">
                  <div className="panel-header compact">
                    <div>
                      <span className="section-kicker">PROGRESS</span>
                      <h2>Task status</h2>
                    </div>
                  </div>
                  <div className="progress-ring" style={{ '--progress': `${Math.round((stats.completed / (stats.total || 1)) * 100)}%` }}>
                    <div><strong>{stats.total ? Math.round((stats.completed / stats.total) * 100) : 0}%</strong><span>completed</span></div>
                  </div>
                  <div className="progress-legend">
                    {taskBreakdown.map((item) => <div key={item.label}><span className={`legend-dot ${item.className}`} /><span>{item.label}</span><strong>{item.percent}%</strong></div>)}
                  </div>
                </section>

                <section className="panel activity-panel">
                  <div className="panel-header compact">
                    <div>
                      <span className="section-kicker">LATEST</span>
                      <h2>Activity</h2>
                    </div>
                  </div>
                  {notifications.slice(0, 4).map((item, index) => (
                    <div className="activity-item" key={item._id || index}>
                      <div className="activity-dot">{index + 1}</div>
                      <div><strong>{item.title || 'Workspace update'}</strong><span>{item.message || 'A new activity was recorded.'}</span></div>
                    </div>
                  ))}
                  {!loading && !notifications.length && <p className="empty-text">No recent activity.</p>}
                </section>
              </aside>
            </div>
          </div>
        </main>
      </div>
    </div>
  );
}

function SidebarSection({ title, items, notificationCount = 0 }) {
  return <div className="menu-section"><p>{title}</p>{items.map((item) => <button className={`menu-item ${item.active ? 'active' : ''}`} type="button" key={item.label}><span className="menu-icon">{item.icon}</span>{item.label}{item.label === 'Notifications' && notificationCount > 0 ? <b className="notification-count">{notificationCount > 9 ? '9+' : notificationCount}</b> : null}</button>)}</div>;
}

function StatCard({ title, value, helper, icon, tone, loading }) {
  return <div className={`stat-card ${tone}`}><div className="stat-icon">{icon}</div><div className="stat-copy"><span>{title}</span><strong>{loading ? '—' : value}</strong><small>{helper}</small></div><span className="stat-arrow">↗</span></div>;
}

function ProjectCard({ project, index, taskCount }) {
  const colors = ['orange', 'pink', 'peach'];
  const progress = Math.min(100, taskCount ? Math.min(90, 20 + taskCount * 10) : 0);
  const members = Array.isArray(project.members) ? project.members : [];
  return <article className={`project-card ${colors[index % colors.length]}`}><div className="project-card-top"><div className="project-logo">{String(project.name || 'P').charAt(0).toUpperCase()}</div><button className="more-btn" type="button">•••</button></div><h3>{project.name}</h3><p>{project.description || 'Keep your team aligned and work moving forward.'}</p><div className="project-meta"><span>{taskCount} tasks</span><span>{members.length || 1} members</span></div><div className="project-progress"><div><span style={{ width: `${progress}%` }} /></div><strong>{progress}%</strong></div></article>;
}

function TaskRow({ task }) {
  const priority = task.priority || 'medium';
  const status = task.status || 'pending';
  return <div className="task-row"><div className="task-check">{task.completed || status === 'completed' ? '✓' : ''}</div><div className="task-title"><strong>{task.title || 'Untitled task'}</strong><span>{task.taskType || 'Standard'}{task.project?.name ? ` · ${task.project.name}` : ''}</span></div><div className="task-date">{formatDate(task.dueDate)}</div><span className={`priority-badge ${priority}`}>{capitalize(priority)}</span><span className={`status-badge ${status}`}>{formatStatus(status)}</span></div>;
}

function LoadingCards() { return <>{[1, 2, 3].map((n) => <div className="skeleton project-card" key={n}><div /><div /><div /><div /></div>)}</>; }
function TaskLoadingRows() { return <>{[1, 2, 3, 4].map((n) => <div className="skeleton-row" key={n}><span /><span /><span /><span /></div>)}</>; }
function EmptyCard({ text }) { return <div className="empty-card">{text}</div>; }
function formatDate(date) { if (!date) return 'No due date'; const d = new Date(date); if (Number.isNaN(d.getTime())) return 'No due date'; return d.toLocaleDateString('en-IN', { day: '2-digit', month: 'short' }); }
function capitalize(value) { return value ? value.charAt(0).toUpperCase() + value.slice(1) : ''; }
function formatStatus(value) { return value === 'in-progress' ? 'In progress' : value === 'completed' ? 'Completed' : 'Pending'; }
function getInitials(name) { return String(name || 'U').split(' ').filter(Boolean).slice(0, 2).map((part) => part[0]).join('').toUpperCase(); }

export default Dashboard;
